#pragma once

#include <Arduino.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>

// Spoken feedback (Turkish) and short tones, played from /sounds on the SD card.
// The files are generated by tools/sounds/gen_prompts.py; the list and the triggers are
// documented in docs/VOICE-PROMPTS.md. A prompt may interrupt a story (resumed afterwards at
// the same position), be dropped while a story plays, or wait for silence - see the policy
// table in VoicePrompts.cpp.
enum class Prompt : uint8_t
{
    SETUP_WELCOME,      // not provisioned: open the app and add the device
    SETUP_CONNECTING,   // credentials received over BLE
    SETUP_SUCCESS,      // first connection after provisioning
    SETUP_FAILED,       // credentials rejected
    WIFI_LOST,          // provisioned, but no network for a minute
    WIFI_RESET_HINT,    // how to forget the network (button combo)
    WIFI_RESET_DONE,    // combo executed
    IDLE_HELLO,         // provisioned boot without a figure
    NFC_READ_TROUBLE,   // figure on the pins, no card read
    FIGURE_NO_CONTENT,  // portal knows the figure but it has no stories (Elma)
    FIGURE_OFFLINE,     // portal unreachable and nothing cached (Armut)
    DOWNLOAD_START,     // new figure, stories being downloaded
    DOWNLOAD_DONE,      // first story ready
    DOWNLOAD_FAILED,    // nothing could be downloaded (Kiraz)
    DOWNLOAD_WAIT,      // the cached stories ended, the next one is still downloading
    PLAYLIST_END,       // last story finished
    BATTERY_LOW,        // on battery, 20 % and every 5 % below
    BATTERY_CRITICAL,   // shutting down
    CHARGE_FULL,        // charger terminated
    UPDATE_START,       // OTA download started
    UPDATE_DONE,        // first boot on a new firmware
    UPDATE_FAILED,      // OTA failed (Karpuz)
    TONE_CHARGE_ON,     // charger plugged
    TONE_CHARGE_OFF,    // charger unplugged
    TONE_SLEEP,         // going to sleep
    COUNT
};

class VoicePrompts
{
public:
    static VoicePrompts &getInstance();

    void begin();                                 // loop task, after the audio controller is up
    void say(Prompt p);                           // any task: queue it, the policy decides
    void sayBlocking(Prompt p, uint32_t maxMs);   // loop task only: play now and wait (sleep, reset)
    void update();                                // loop task, every iteration
    bool isBusy() const;                          // a prompt is playing
    String path(Prompt p) const;                  // /sounds/tr/<name>.mp3 or /sounds/<tone>.mp3
    bool available(Prompt p) const;               // the file exists on the card
    void setLanguage(const String &code) { language = code; }
    static const char *name(Prompt p);

private:
    VoicePrompts() = default;
    struct Policy
    {
        bool interrupt;          // may interrupt a playing story (resumed afterwards)
        bool dropWhilePlaying;   // otherwise: drop (true) or wait for silence (false)
        uint32_t minIntervalMs;  // the same prompt is not repeated within this window
    };
    static const Policy &policy(Prompt p);
    bool playNow(Prompt p);

    QueueHandle_t queue = nullptr;
    uint32_t queuedMask = 0;
    uint32_t lastSaidAt[(int)Prompt::COUNT] = {};
    int waitingPrompt = -1;               // dequeued, waiting for silence
    unsigned long waitingSince = 0;
    String language = "tr";
    bool started = false;
};
